<template>
  <Dialog v-model:open="model">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent :class="cn('rounded-lg max-w-xs sm:max-w-sm gap-6', modalClass)">
      <DialogHeader class="gap-y-2 text-left">
        <DialogTitle class="text-xl">{{ title }}</DialogTitle>
        <DialogDescription v-if="description" class="font-normal text-base text-accent-foreground w-full">
          <div v-html="description || ''" />
        </DialogDescription>
        <slot name="description" />
      </DialogHeader>
      <DialogFooter>
        <div class="flex flex-wrap justify-end gap-2">
          <DialogClose as-child>
            <Button variant="outline" class="h-10 px-4">Cancel</Button>
          </DialogClose>
          <Button :variant="confirmBtnVariant" class="h-10 px-4" :loading="isConfirmLoading" @click="onConfirm">
            {{ confirmBtnText }}
          </Button>
        </div>
      </DialogFooter>
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
import type { ButtonVariants } from '~/components/ui/button';
import { cn } from '@/lib/utils';

interface Props {
  title?: string;
  description?: string;
  confirmBtnVariant?: ButtonVariants['variant'];
  confirmBtnText?: string;
  isConfirmLoading?: boolean;
  modalClass?: string;
  confirmHandler?: () => Promise<any>;
}

interface Emits {
  (e: 'confirm'): void;
}

const props = withDefaults(defineProps<Props>(), {
  title: 'Confirm action?',
  description: undefined,
  confirmBtnVariant: 'destructive',
  confirmBtnText: 'Confirm',
  modalClass: undefined,
  confirmHandler: undefined,
});

const emit = defineEmits<Emits>();

const model = defineModel<boolean>({
  default: false,
});

async function onConfirm() {
  if (props.confirmHandler) {
    await props.confirmHandler();
  }
  emit('confirm');
  model.value = false;
}
</script>

<style scoped lang="scss"></style>
